entries[127828] = { ["name"] = "Dazzling Rod", ["text"] = "Binds when picked up\nMain Hand\n1 Arcane Damage Speed 1.60\n(0.6 damage per second)\nUse: Fire a quick moving orb of arcane energy.\n\nCan only hit players using the Dazzling Rod.\nSell Price:" }
entries[127829] = { ["name"] = "Twinblades of the Deceiver", ["text"] = "Verus\nBinds when picked up\nUnique\nMain Hand Warglaive\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nFel Artifact Relic Slot\nShadow Artifact Relic Slot\n\nClasses: Demon Hunter\nEquip: Grants the Fury of the Illidari ability, which repeatedly slashes all nearby enemies with your warglaives.\n\"Make examples of those foolish enough to oppose you, and the rest of their kind will grovel at your feet.\"\nSell Price:" }
entries[127830] = { ["name"] = "Twinblades of the Deceiver", ["text"] = "Muramas\nBinds when picked up\nUnique\nOff Hand Warglaive\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Demon Hunter\n\"The end has come! Let the unravelling of this world commence!\"\nSell Price:" }
