entries[127837] = { ["name"] = "Draught of Raw Magic", ["text"] = "Use: Chug it.\nSell Price:" }
entries[127838] = { ["name"] = "Sylvan Elixir", ["text"] = "Use: Transform into a tree. You and any players that rest in your shade become Well-Rested, increasing all stats by 10%.\nSell Price:" }
entries[127839] = { ["name"] = "Avalanche Elixir", ["text"] = "Use: Falling a great distance will cause you to transform into an avalanche. When you land, deal 1500 damage to all enemies within 5 yards. (5 Min Cooldown)\nSell Price:" }
entries[127840] = { ["name"] = "Skaggldrynk", ["text"] = "Use: Enter the spirit realm, giving the imbiber invisibility for 18 sec. Ineffective above level 50. (5 Min Cooldown)\nSell Price:" }
entries[127841] = { ["name"] = "Skystep Potion", ["text"] = "Use: Increases movement speed by 150% and allows the imbiber to hover. Lasts 8 sec. Ineffective above level 50. (5 Min Cooldown)\nSell Price:" }
entries[127842] = { ["name"] = "Infernal Alchemist Stone", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 19 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Legion Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:" }
entries[127843] = { ["name"] = "Potion of Deadly Grace", ["text"] = "Use: Grants your attacks a chance to unleash a bolt of energy at your target.\n\nStaying away from enemies for the entire duration of the effect will extend the effect by an additional 5 seconds. (5 Min Cooldown)\nSell Price:" }
entries[127844] = { ["name"] = "Potion of the Old War", ["text"] = "Use: Summons a pair of ghostly fallen warriors that will join you in combat. They may echo your melee attacks and abilities, dealing 1161 damage. (5 Min Cooldown)\nSell Price:" }
entries[127845] = { ["name"] = "Unbending Potion", ["text"] = "Use: Increases your Armor by 124 for 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[127846] = { ["name"] = "Leytorrent Potion", ["text"] = "Use: Puts the imbiber in an elevated state of focus where they can restore up to ( 300 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:" }
entries[127847] = { ["name"] = "Flask of the Whispered Pact", ["text"] = "Use: Increases Intellect by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:" }
entries[127848] = { ["name"] = "Flask of the Seventh Demon", ["text"] = "Use: Increases Agility by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:" }
entries[127849] = { ["name"] = "Flask of the Countless Armies", ["text"] = "Use: Increases Strength by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:" }
entries[127850] = { ["name"] = "Flask of Ten Thousand Scars", ["text"] = "Use: Increases Stamina by 69 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:" }
entries[127851] = { ["name"] = "Spirit Cauldron", ["text"] = "Binds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 30 uses and lasts for 10 min.\nSell Price:" }
entries[127852] = { ["name"] = "Armaments of the Black Wyrm [TEMP]", ["text"] = "Binds when picked up\nMain Hand Sword\n5 - 8 Damage Speed 2.60\n(2.5 damage per second)\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\n\"Crafted from a scale of Neltharion, the sword Icebreaker and the shield Scale of the Earthwarder.\"\nSell Price:" }
entries[127853] = { ["name"] = "Iron Fleet Treasure Chest", ["text"] = "Normal\nBinds when picked up\n\"Contains a Normal mode item from the Hellfire Citadel raid zone.\"\n<Right Click to Open>" }
entries[127854] = { ["name"] = "Iron Fleet Treasure Chest", ["text"] = "Heroic\nBinds when picked up\n\"Contains a Heroic quality item from the Hellfire Citadel raid zone.\"\n<Right Click to Open>" }
entries[127855] = { ["name"] = "Iron Fleet Treasure Chest", ["text"] = "Mythic\nBinds when picked up\n\"Contains a Mythic quality item from the Hellfire Citadel raid zone.\"\n<Right Click to Open>" }
entries[127856] = { ["name"] = "Left Shark", ["text"] = "Use: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Left Shark.\nRequires level 1 to 80 ( 80)" }
entries[127857] = { ["name"] = "Aluneth", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nArcane Artifact Relic Slot\nFrost Artifact Relic Slot\n\nClasses: Mage\nEquip: Grants the Mark of Aluneth ability, which places a rune on the ground that explodes for massive damage after a short delay.\n\"After many setbacks, Aegwynn finally bound the entity to an enchanted greatstaff. The task of containing Aluneth was done, but it would take the Guardian years to truly harness its power.\"\nSell Price:" }
entries[127858] = { ["name"] = "Spirit Flask", ["text"] = "Conjured Item\nUnique: Guild Flask (1)\nUse: Grants the effect of a flask based on your class and talents. Lasts 1 hour and persists through death. (3 Sec Cooldown)" }
entries[127859] = { ["name"] = "Dazzling Rod", ["text"] = "Binds when picked up\nToy\nUse: Equip a Dazzling Rod, allowing you to shoot arcane energy at others wielding the rod. (5 Sec Cooldown)\n\"A game played by Draenic children.\"" }
