entries[127882] = { ["name"] = "Blast Furnace", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with a Blast Furnace.\n\nCounters:\nSwift\nRequires Blast Furnace Blueprint." }
