entries[127885] = { ["name"] = "Salty Crew", ["text"] = "Binds when picked up\nUse: Hire a Salty Crew for your naval ship.\n\"This crew has seen it all and has the hats to prove it. Increases success chance on missions by 10%.\"" }
entries[127886] = { ["name"] = "Unsinkable", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with Unsinkable.\n\nOn a devastating hit Unsinkable surrounds the ship with an impenetrable shield, saving it. Unsinkable is destroyed when triggered.\nRequires Blueprint, last seen on a vendor in Tanaan Jungle.\nSell Price:" }
entries[127887] = { ["name"] = "Food Storage Bay", ["text"] = "Binds when picked up\nUse: Equip a naval ship with a Food Storage Bay.\n\"Adds space for additional food stores, improving morale and success chance on long missions.\"" }
entries[127888] = { ["name"] = "Automated Sky Scanner", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with an Automated Sky Scanner.\n\nAssist: Carrier\nSell Price:" }
entries[127889] = { ["name"] = "Ammo Reserves", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with Ammo Reserves.\n\nAssist: Battleship\nSell Price:" }
entries[127890] = { ["name"] = "Sonic Amplification Field", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with a Sonic Amplification Field.\n\nAssist: Destroyer\nSell Price:" }
entries[127891] = { ["name"] = "Extra Quarters", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with Extra Quarters.\n\nAssist: Transport\nSell Price:" }
entries[127892] = { ["name"] = "Q-43 Noisemaker Mines", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with Q-43 Noisemaker Mines.\n\nAssist: Submarine\nSell Price:" }
entries[127893] = { ["name"] = "Wreckage Recovery Module", ["text"] = "Binds when picked up\nUse: Equip a naval ship with a Wreckage Recovery Module.\n\"When deployed on a successful mission, filters the surrounding waters and returns a box full of useful junk.\"" }
entries[127894] = { ["name"] = "Tuskarr Fishing Net", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with a Tuskarr Fishing Net.\n\nA fishing net attached to the back of the boat, courtesy of the tuskarr. Supplies fish when returning from a successful mission.\nRequires Blueprint, last seen on a vendor in Tanaan Jungle.\nSell Price:" }
entries[127895] = { ["name"] = "Ghostly Spyglass", ["text"] = "Naval Equipment\nBinds when picked up\nUse: Equip a ship with a Ghostly Spyglass.\n\nA long spyglass that seems to display nothing when you look through it. Maybe it will come in handy.\nRequires Ghostly Spyglass Blueprint.\nSell Price:" }
entries[127896] = { ["name"] = "Nitro Fuel Tanks", ["text"] = "Binds when picked up\nUse: Equip a naval ship with Nitro Fuel Tanks.\n\"Allows the ship to burn nitro fuel, getting it to and from destinations quicker.\"" }
entries[127897] = { ["name"] = "The Sword of Truth", ["text"] = "Quest Item\nUse: Plant Ravencrest's sword into the ground at the desired location. (3 Sec Cooldown)\n\"Beneath a thick layer of grime and dirt, the blade shines.\"" }
entries[127898] = { ["name"] = "Recipe: Ancient Healing Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Ancient Healing Potion.\nMix an Ancient Healing Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nSell Price:\nAncient Healing Potion\nUse: Restores 6000 health. (5 Min Cooldown)\nSell Price:\nRequires Yseralline Seed (4), Crystal Vial" }
entries[127899] = { ["name"] = "Recipe: Ancient Mana Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Ancient Mana Potion.\nMix an Ancient Mana Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nSell Price:\nAncient Mana Potion\nUse: Restores 2000 mana. (5 Min Cooldown)\nSell Price:\nRequires Yseralline Seed (5), Crystal Vial" }
entries[127900] = { ["name"] = "Recipe: Ancient Rejuvenation Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Ancient Rejuvenation Potion.\nMix an Ancient Rejuvenation Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nSell Price:\nAncient Rejuvenation Potion\nUse: Restores 6000 health and 1500 mana. (5 Min Cooldown)\nSell Price:\nRequires Ancient Healing Potion , Ancient Mana Potion" }
entries[127901] = { ["name"] = "Recipe: Draught of Raw Magic", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Draught of Raw Magic.\nMix a Draught of Raw Magic at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Leyflame Burner\nSell Price:\nDraught of Raw Magic\nUse: Chug it.\nSell Price:\nRequires Aethril (20), Ancient Healing Potion" }
entries[127902] = { ["name"] = "Recipe: Sylvan Elixir", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Sylvan Elixir.\nMix a Sylvan Elixir at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Advanced Corks\nSell Price:\nSylvan Elixir\nUse: Transform into a tree. You and any players that rest in your shade become Well-Rested, increasing all stats by 10%.\nSell Price:\nRequires Dreamleaf (5), Ancient Healing Potion" }
entries[127903] = { ["name"] = "Recipe: Avalanche Elixir", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Avalanche Elixir.\nMix an Avalanche Elixir at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Dual-Chambered Mixing Flask\nSell Price:\nAvalanche Elixir\nUse: Falling a great distance will cause you to transform into an avalanche. When you land, deal 1500 damage to all enemies within 5 yards. (5 Min Cooldown)\nSell Price:\nRequires Foxflower (5), Ancient Mana Potion" }
entries[127904] = { ["name"] = "Recipe: Skaggldrynk", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make Skaggldrynk.\nMix a Skaggldrynk at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Precipitating Powder\nSell Price:\nSkaggldrynk\nUse: Enter the spirit realm, giving the imbiber invisibility for 18 sec. Ineffective above level 50. (5 Min Cooldown)\nSell Price:\nRequires Fjarnskaggl (5), Ancient Mana Potion" }
entries[127905] = { ["name"] = "Recipe: Skystep Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Skystep Potion.\nMix a Skystep Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Shaldorei Silk Filter\nSell Price:\nSkystep Potion\nUse: Increases movement speed by 150% and allows the imbiber to hover. Lasts 8 sec. Ineffective above level 50. (5 Min Cooldown)\nSell Price:\nRequires Starlight Rose (4), Ancient Rejuvenation Potion" }
entries[127906] = { ["name"] = "Recipe: Infernal Alchemist Stone", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Infernal Alchemist Stone.\nCraft an Infernal Alchemist Stone at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Demonsbreath Crucible\nSell Price:\nInfernal Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 19 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Legion Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Infernal Brimstone , Felwort (5), Blood of Sargeras (3)" }
entries[127907] = { ["name"] = "Recipe: Potion of Deadly Grace", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Potion of Deadly Grace.\nMix a Potion of Deadly Grace at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Advanced Corks, Bendy Glass Tubes, and Shaldorei Silk Filter\nSell Price:\nPotion of Deadly Grace\nUse: Grants your attacks a chance to unleash a bolt of energy at your target.\n\nStaying away from enemies for the entire duration of the effect will extend the effect by an additional 5 seconds. (5 Min Cooldown)\nSell Price:\nRequires Starlight Rose , Fjarnskaggl (2), Dreamleaf (2), Crystal Vial" }
entries[127908] = { ["name"] = "Recipe: Potion of the Old War", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Potion of the Old War.\nMix a Potion of the Old War at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Advanced Corks, Bendy Glass Tubes, and Precipitating Powder\nSell Price:\nPotion of the Old War\nUse: Summons a pair of ghostly fallen warriors that will join you in combat. They may echo your melee attacks and abilities, dealing 1161 damage. (5 Min Cooldown)\nSell Price:\nRequires Starlight Rose , Foxflower (2), Fjarnskaggl (2), Crystal Vial" }
entries[127909] = { ["name"] = "Recipe: Unbending Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Unbending Potion.\nMix an Unbending Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Advanced Corks, Bendy Glass Tubes, and Dual-Chambered Mixing Flask\nSell Price:\nUnbending Potion\nUse: Increases your Armor by 124 for 25 sec. (5 Min Cooldown)\nSell Price:\nRequires Starlight Rose , Aethril (2), Foxflower (2), Crystal Vial" }
entries[127910] = { ["name"] = "Recipe: Leytorrent Potion", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Leytorrent Potion.\nMix a Leytorrent Potion at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Advanced Corks, Bendy Glass Tubes, and Leyflame Burner\nSell Price:\nLeytorrent Potion\nUse: Puts the imbiber in an elevated state of focus where they can restore up to ( 300 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:\nRequires Starlight Rose , Aethril (2), Dreamleaf (2), Crystal Vial" }
entries[127911] = { ["name"] = "Recipe: Flask of the Whispered Pact", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Flask of the Whispered Pact.\nMix a Flask of the Whispered Pact at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Demonsbreath Crucible, Malloric Burette Assembly, and Shaldorei Silk Filter\nSell Price:\nFlask of the Whispered Pact\nUse: Increases Intellect by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Fjarnskaggl (10), Dreamleaf (10), Crystal Vial" }
entries[127912] = { ["name"] = "Recipe: Flask of the Seventh Demon", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Flask of the Seventh Demon.\nMix a Flask of the Seventh Demon at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Demonsbreath Crucible, Malloric Burette Assembly, and Precipitating Powder\nSell Price:\nFlask of the Seventh Demon\nUse: Increases Agility by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Foxflower (10), Fjarnskaggl (10), Crystal Vial" }
entries[127913] = { ["name"] = "Recipe: Flask of the Countless Armies", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Flask of the Countless Armies.\nMix a Flask of the Countless Armies at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Demonsbreath Crucible, Malloric Burette Assembly, and Dual-Chambered Mixing Flask\nSell Price:\nFlask of the Countless Armies\nUse: Increases Strength by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Aethril (10), Foxflower (10), Crystal Vial" }
entries[127914] = { ["name"] = "Recipe: Flask of Ten Thousand Scars", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Flask of Ten Thousand Scars.\nMix a Flask of Ten Thousand Scars at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires Demonsbreath Crucible, Malloric Burette Assembly, and Leyflame Burner\nSell Price:\nFlask of Ten Thousand Scars\nUse: Increases Stamina by 69 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Aethril (10), Dreamleaf (10), Crystal Vial" }
entries[127915] = { ["name"] = "Recipe: Spirit Cauldron", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Spirit Cauldron.\nCraft a Spirit Cauldron at the Dalaran Alchemy Station.\nRequires Legion Alchemy (100)\nRequires High-Capacity Decoction Conduit\nSell Price:\nSpirit Cauldron\nBinds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 30 uses and lasts for 10 min.\nSell Price:\nRequires Flask of the Whispered Pact (5), Flask of the Seventh Demon (5), Flask of the Countless Armies (5), Flask of Ten Thousand Scars (5), Blood of Sargeras" }
entries[127916] = { ["name"] = "Altruis' Findings", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Someone on Azsuna is bound to know of the Pillars of Creation.\"" }
