entries[127949] = { ["name"] = "Recipe: Flask of the Seventh Demon", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make a Flask of the Seventh Demon.\nChance to create multiple flasks.\nRequires Legion Alchemy (1)\nSell Price:\nFlask of the Seventh Demon\nUse: Increases Agility by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Foxflower (10), Fjarnskaggl (10), Crystal Vial" }
entries[127950] = { ["name"] = "Recipe: Flask of the Countless Armies", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make a Flask of the Countless Armies.\nChance to create multiple flasks.\nRequires Legion Alchemy (1)\nSell Price:\nFlask of the Countless Armies\nUse: Increases Strength by 46 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Aethril (10), Foxflower (10), Crystal Vial" }
entries[127951] = { ["name"] = "Recipe: Flask of Ten Thousand Scars", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make a Flask of Ten Thousand Scars.\nChance to create multiple flasks.\nRequires Legion Alchemy (1)\nSell Price:\nFlask of Ten Thousand Scars\nUse: Increases Stamina by 69 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Starlight Rose (7), Aethril (10), Dreamleaf (10), Crystal Vial" }
entries[127952] = { ["name"] = "Recipe: Spirit Cauldron", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make a Spirit Cauldron.\nChance to create multiple cauldrons.\nRequires Legion Alchemy (100)\nSell Price:\nSpirit Cauldron\nBinds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 30 uses and lasts for 10 min.\nSell Price:\nRequires Flask of the Whispered Pact (5), Flask of the Seventh Demon (5), Flask of the Countless Armies (5), Flask of Ten Thousand Scars (5), Blood of Sargeras" }
