entries[128402] = { ["name"] = "Maw of the Damned", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Axe\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nBlood Artifact Relic Slot\nShadow Artifact Relic Slot\n\nClasses: Death Knight\nEquip: Grants the Consumption ability, which deals massive damage and returns health to the wielder.\n\"The Maw's thirst is unquenchable. If it is not fed fresh victims, it will not hesitate to drink from its wielder instead.\"\nSell Price:" }
entries[128403] = { ["name"] = "Apocalypse", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nFire Artifact Relic Slot\nShadow Artifact Relic Slot\n\nClasses: Death Knight\nEquip: Grants the Apocalypse ability, which summons members of your Army of the Dead to fight for you. (Proc chance: 5%, 10m cooldown)\n\"It shall sow destruction and war. Famine and death. It shall tempt with power, and then bring an end to all life.\"\nSell Price:" }
