entries[128526] = { ["name"] = "Deathtusk Felboar", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Deathtusk Felboar .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Vol'jin's Headhunters\n- Exalted\nSell Price:\n\"Veterans of the battle for Outland's Hellfire Peninsula are traumatized by thoughts of these beasts to this day.\"\nVendor:\nShadow Hunter Denjai\nZone:\nTanaan Jungle\nFaction:\nVol'jin's Headhunters - Exalted\n\nVendor:\nVindicator Krethos\nZone:\nTanaan Jungle\nFaction:\nHand of the Prophet - Exalted" }
